import AppKit
import SwiftUI

/// Genie の印（ランプと G、右上の星）。元の絵は `apps/genie-macos/Resources/GenieMark-source.png`。
///
/// 黒の形だけを alpha に持つ **template 画像**（色は使う側が決める）。資源の束ねを持たない
/// SwiftPM の target なので、小さな PNG（96px 高）をここに埋める。app icon は同じ絵から作った
/// `Resources/AppIcon.icns`。
enum GenieBrandMark {
    /// 横 ÷ 縦（964 × 582）。
    static let aspect: CGFloat = 964.0 / 582.0
    /// 簡略版（G を外したランプと星、781 × 582）。元の絵は `Resources/GenieMark-small-source.png`。
    static let smallAspect: CGFloat = 781.0 / 582.0
    /// これ以下の高さでは簡略版を使う。13pt のメニューバー・12pt の Dock では G の渦と蓋が潰れる。
    static let smallThreshold: CGFloat = 16

    static let image: NSImage = template(png)
    static let small: NSImage = template(smallPng)

    private static func template(_ base64: String) -> NSImage {
        let image = NSImage(data: Data(base64Encoded: base64) ?? Data()) ?? NSImage()
        image.isTemplate = true
        return image
    }

    /// 高さに合う方（16pt 以下は簡略版）。
    static func mark(forHeight height: CGFloat) -> (image: NSImage, aspect: CGFloat) {
        height <= smallThreshold ? (small, smallAspect) : (image, aspect)
    }

    /// 高さ `height` pt の template 画像（メニューバー用）。
    static func image(height: CGFloat) -> NSImage {
        let (source, ratio) = mark(forHeight: height)
        let copy = source.copy() as? NSImage ?? source
        copy.size = NSSize(width: (height * ratio).rounded(), height: height)
        copy.isTemplate = true
        return copy
    }

    private static let smallPng = ""

    private static let png = ""
}

/// SwiftUI で色を付けて描く印。
struct GenieBrandMarkView: View {
    var height: CGFloat = 12
    var color: Color = .genieAccent

    var body: some View {
        let mark = GenieBrandMark.mark(forHeight: height)
        Image(nsImage: mark.image)
            .renderingMode(.template)
            .resizable()
            .interpolation(.high)
            .aspectRatio(mark.aspect, contentMode: .fit)
            .frame(height: height)
            .foregroundStyle(color)
            .accessibilityHidden(true)
    }
}
